
CREATE TABLE gallery_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),uploaded_by uuid NOT NULL REFERENCES users(id),title text NOT NULL DEFAULT '',caption text NOT NULL DEFAULT '',alt_text text NOT NULL,display_key text NOT NULL UNIQUE,thumbnail_key text NOT NULL UNIQUE,mime_type text NOT NULL,width int NOT NULL CHECK(width>0),height int NOT NULL CHECK(height>0),display_size_bytes bigint NOT NULL CHECK(display_size_bytes>0),taken_at timestamptz,published_at timestamptz,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'PUBLISHED' OR published_at IS NOT NULL));
CREATE INDEX gallery_recent ON gallery_images((COALESCE(taken_at,published_at)) DESC,id DESC) WHERE status='PUBLISHED';
